40class Issue {
41
42    // store book issued by student
43    HashMap<Integer, String> issue = new HashMap<>();
44
45    Scanner input = new Scanner(System.in);
46
47    Book b1 = new Book();
48    Student s1 = new Student();
49
50    public Issue() {
51
52        // add elements to student HashMap
53        s1.add();
54
55        // add elements to book HashMap
56        b1.add();
57    }
58
59    // method to issue book
60    void issueBook(int id) {
61
62        System.out.println("enter a book");
63        String bookName = input.nextLine();
64
65
66        // check if book is inside the book hashmap
67        if (b1.book.containsValue(bookName)) {
68
69            // get book id to remove it from the book HashMap
70            int bookId = 0;
71            // iterate each entry of hashmap
72            for (Entry<Integer, String> entry : b1.book.entrySet()) {
73
74                // get bookId from bookName
75                if (entry.getValue().equals(bookName)) {
76                    bookId = entry.getKey();
77                    break;
78                }
79            }
80
81            // remove book from the book hashmap
82            b1.book.remove(bookId);
83            
84            // add value of student id and book to issue hashmap
85            issue.put(id, bookName);
86
87            // get student name from id
88            String name = s1.student.get(id);
89            
90            // print name and issued book
91            System.out.println("Name: " + name);
92            System.out.println("Book: " + bookName);
93            System.out.println("Book issued Congratulation");
94        }
95
96        else {
97            System.out.println("Book doesn't exist");
98            System.out.println("We have following Books:");
99            System.out.println(b1.book);
100        }
101    }
102
